-- Bolt 40-4（SC-INV-04）。有人案件の受領・回答期限を数える営業日カレンダー。日ごとの営業日・営業時間を持つ（data_model の business_calendar）。
-- H2 と PostgreSQL の共通の構文で書く（ADR-007）。
CREATE TABLE tracking.business_calendar (
    calendar_date DATE         NOT NULL,
    business_day  BOOLEAN      NOT NULL,
    open_time     TIME,
    close_time    TIME,
    time_zone     VARCHAR(50)  NOT NULL,
    note          VARCHAR(200),
    CONSTRAINT pk_business_calendar PRIMARY KEY (calendar_date),
    CONSTRAINT ck_business_calendar_hours CHECK (
        (business_day = TRUE AND open_time IS NOT NULL AND close_time IS NOT NULL AND open_time < close_time)
        OR (business_day = FALSE AND open_time IS NULL AND close_time IS NULL))
);

COMMENT ON TABLE tracking.business_calendar IS '営業日カレンダー（日ごとの営業日・営業時間。年次で翌年分を登録する）';
COMMENT ON COLUMN tracking.business_calendar.calendar_date IS '日付（現地）';
COMMENT ON COLUMN tracking.business_calendar.business_day IS '営業日か';
COMMENT ON COLUMN tracking.business_calendar.open_time IS '開始（営業日だけ。営業時間は開始以上、終了未満）';
COMMENT ON COLUMN tracking.business_calendar.close_time IS '終了（営業日だけ）';
COMMENT ON COLUMN tracking.business_calendar.time_zone IS '時間帯（IANA）';
COMMENT ON COLUMN tracking.business_calendar.note IS '備考（祝日の名前など）';

-- 見本: 2026・2027 年の全日。日本の祝日は内閣府の定めから作った見本で、業務責任者の確認を要する。翌年以降は運用タスク calendar:register（W10）で登録する。
